template <int N>
struct Factorial {
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Specialization provides the base case (polymorphism point)
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Trait usage in a static context
template <typename T>
struct is_pointer {
    static constexpr bool value = false;
};

template <typename T>
struct is_pointer<T*> {
    static constexpr bool value = true;
};

constexpr int fact_val = Factorial<5>::value;
// fact_val == 120 (Compile-time computation)

// Compile-time trait check
constexpr bool check = is_pointer<int*>::value; // true
